package com.omepikya.commandcenter.nlp;
import com.omepikya.commandcenter.core.CommandType;import java.util.Locale;
public class CommandMatcher {
 public CommandType match(String command){if(command==null||command.trim().isEmpty())return CommandType.UNKNOWN;String t=command.toLowerCase(Locale.US).trim().replaceAll("\\s+"," ");if(settings(t))return CommandType.SYSTEM_SETTING;if(any(t,"search for ","search the web for ","google "))return CommandType.WEB_SEARCH;if(any(t,"navigate to ","directions to ","direction to ","take me to ","show me the way to ","map "))return CommandType.NAVIGATION;if(starts(t,"call","phone","dial","ring")||(t.startsWith("give ")&&t.contains(" a call")))return CommandType.COMMUNICATION;if(starts(t,"message","text","sms","whatsapp")||any(t,"send a message","send message","send sms","send an sms","send whatsapp"))return CommandType.COMMUNICATION;if(any(t,"play music","pause music","resume music","play media","pause media","resume media","next track","previous track","skip track")||t.equals("play")||t.equals("pause")||t.equals("resume"))return CommandType.MEDIA;if(any(t,"battery status","battery information","battery info"))return CommandType.DEVICE_ACTION;if(starts(t,"open","launch","start"))return CommandType.OPEN_APP;if(starts(t,"close","exit"))return CommandType.CLOSE_APP;if(any(t,"alarm","remind","reminder","schedule","timer","every morning","every day","every monday"))return CommandType.AUTOMATION;if(starts(t,"what","who","where","when","why","how"))return CommandType.INFORMATION;return CommandType.UNKNOWN;}
 private boolean starts(String t,String...v){for(String x:v)if(t.equals(x)||t.startsWith(x+" "))return true;return false;}private boolean any(String t,String...v){for(String x:v)if(t.contains(x))return true;return false;}private boolean settings(String t){return any(t,"settings","setting","wifi","wi-fi","bluetooth","display","brightness","screen timeout","sound","volume","audio","airplane mode","flight mode","mobile data","mobile network","cellular data","cellular network","location settings","gps settings","location services","notification");}
}
